import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import api from "../api"; 

const ROLES = [
  {id:"student",label:"Student",emoji:"🎓",desc:"Find internships",sel:"border-blue-500 bg-blue-50"},
  {id:"company",label:"Company",emoji:"🏢",desc:"Post offers",sel:"border-slate-700 bg-slate-100"},
];

export default function Register() {
  const [step, setStep]       = useState(1);
  const [role, setRole]       = useState(null);
  const [showPass, setShowPass] = useState(false);
  const [form, setForm]       = useState({fullname:"", email:"", password:""});
  const [loading, setLoading]   = useState(false);
  

  const upd = (k,v) => setForm(f=>({...f,[k]:v}));

  const canSubmit = form.fullname.length > 3 && form.email.includes("@") && form.password.length >= 8;

  const handleRegister = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      // API Call for Registration
      await api.post('register/', {
        username: form.email, // Using email as username
        email: form.email,
        fullname: form.fullname,
        password: form.password,
        role: role
      });
      setStep(3); // Navigate to Success screen
    } catch (error) {
      console.error(error);
      alert(error.response?.data?.username ? "Email already registered" : "Registration failed");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#fdf9f5] flex items-center justify-center p-6">
      <div className="w-full max-w-lg bg-white p-10 rounded-3xl shadow-sm border border-slate-100">
        
        {step === 1 && (
          <div className="animate-in fade-in duration-500">
            <h2 className="text-3xl font-bold text-slate-900 mb-2">Join Stag.io</h2>
            <p className="text-slate-500 mb-8 text-sm">Have an account? <Link to="/login" className="text-blue-600 font-bold">Sign In</Link></p>
            
            <div className="grid grid-cols-2 gap-4 mb-8">
              {ROLES.map(r => (
                <div key={r.id} onClick={() => setRole(r.id)}
                  className={`cursor-pointer border-2 rounded-2xl p-5 text-center transition-all ${role===r.id ? r.sel : "border-slate-100 hover:border-slate-200"}`}>
                  <div className="text-4xl mb-2">{r.emoji}</div>
                  <div className="font-bold text-slate-800">{r.label}</div>
                </div>
              ))}
            </div>

            <button disabled={!role} onClick={() => setStep(2)}
              className={`w-full text-white font-bold py-3 rounded-xl transition-all ${role ? "bg-slate-900 shadow-lg" : "bg-slate-200 cursor-not-allowed"}`}>
              Continue as {role || "..."} →
            </button>
          </div>
        )}

        {step === 2 && (
          <form onSubmit={handleRegister} className="animate-in slide-in-from-right duration-500 space-y-5">
            <button onClick={() => setStep(1)} className="text-xs text-slate-400 mb-4 font-medium hover:text-slate-600">← Change Role</button>
            <h2 className="text-2xl font-bold text-slate-900">Account Details</h2>
            
            <input 
              required
              placeholder="Full Name"
              className="w-full p-3 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
              value={form.fullname}
              onChange={e => upd("fullname", e.target.value)}
            />

            <input 
              required
              type="email"
              placeholder="Email Address"
              className="w-full p-3 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
              value={form.email}
              onChange={e => upd("email", e.target.value)}
            />
            <div className="relative">
              <input 
                required
                type={showPass ? "text" : "password"}
                placeholder="Password (min 8 chars)"
                className="w-full p-3 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
                value={form.password}
                onChange={e => upd("password", e.target.value)}
              />
              <button type="button" onClick={() => setShowPass(!showPass)} className="absolute right-3 top-3 text-slate-400">{showPass ? "🙈" : "👁️"}</button>
            </div>

            <button 
              type="submit"
              disabled={!canSubmit || loading}
              className={`w-full text-white font-bold py-3 rounded-xl transition-all ${canSubmit && !loading ? "bg-blue-600" : "bg-slate-300 cursor-not-allowed"}`}
            >
              {loading ? "Creating Account..." : "Register Now"}
            </button>
          </form>
        )}

        {step === 3 && (
          <div className="text-center animate-in zoom-in duration-500">
            <div className="text-6xl mb-6">🎉</div>
            <h2 className="text-3xl font-bold text-slate-900 mb-2">Welcome Aboard!</h2>
            <p className="text-slate-500 mb-8">Registration successful. Start your journey now.</p>
            <Link to="/login" className="block w-full bg-slate-900 text-white font-bold py-3 rounded-xl shadow-lg">Login to Account</Link>
          </div>
        )}
      </div>
    </div>
  );
}
